def show_application_by_pid(pid):

    #     Activates and displays the window, useful if  window is minimised.
    #     e.g FKPID UI has been hidden and Squish can't interact.
    #
    #     If the window is minimized or maximized, the system restores it to its original size and position.
    #

    import ctypes
    from ctypes import windll
    EnumDesktopWindows = ctypes.windll.user32.EnumDesktopWindows
    GetWindowThreadProcessId = ctypes.windll.user32.GetWindowThreadProcessId
    GetWindow = ctypes.windll.user32.GetWindow
    IsWindowVisible = ctypes.windll.user32.IsWindowVisible
    EnumWindowsProc = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int))
    ShowWindowAsync = windll.user32.ShowWindowAsync

    hwnds = []

    def callback(hwnd, lParam):
        hwnds.append(hwnd)
        return True
    callback_proc = EnumWindowsProc(callback)
    # Run through windows on default desktop and collect hwnd for each
    EnumDesktopWindows(None, callback_proc, 0)

    for h in hwnds:
        # Trawl through window handles for those associated with given pid
        lpid = ctypes.c_ulong()
        GetWindowThreadProcessId(h, ctypes.byref(lpid))
        if lpid.value == pid:
            GW_OWNER = 4
            owner = GetWindow(h, GW_OWNER)
            is_visible = IsWindowVisible(h)
            # Restore application top window
            if owner == 0 and IsWindowVisible(h):
                SW_RESTORE = 9
                ShowWindowAsync(h, SW_RESTORE)
                return True

    return False

def get_xvi_software_build_version_from_config(sri_ini_config_path: str="C:\\XVI\\sri.ini"):
    '''
    Gets the major and minor software build version of the XVI app by reading the
    sri.ini config file on the XVI system. This function is intended to be used
    as an argument to execute_remote_py_function() to run on a remote XVI system.

    Args:
        sri_ini_config_path (str): Path to the XVI sri.ini config file. Default path
                                    set to "C:\\XVI\\sri.ini".
    Returns:
        (List[str] or str): List of strings, the first string is the major version
                            and the second string is the minor version. If the
                            config file cannot be read an empty string is returned
    '''
    # Note: Return type hint not specified in function declaration as an error occurs when
    # executed with execute_remote_py_function() on a remote system as List type is not recognized

    # Library import is included in function definition as function is copied to remote system
    import logging
    import configparser

    # Setup logging on remote system
    logging_level = logging.INFO
    log_path_file = 'C:\\Temp\\software_build_version_retrieval.log'
    FORMAT = "[%(asctime)s - %(levelname)s] - [%(filename)s:%(lineno)s %(funcName)s()] -  %(message)s"
    DATE_FORMAT='%m/%d/%Y %I:%M:%S %p'
    logging.basicConfig(filename=log_path_file,level=logging_level, format=FORMAT, datefmt=DATE_FORMAT)
    logging.info("get_xvi_software_build_version_from_config(): Entry...")

    try:
        # Use standard python configparser package instead of interops version
        # as interops may not be installed on remote system
        config = configparser.ConfigParser()
        config.read(sri_ini_config_path)
        logging.info("get_xvi_software_build_version_from_config(): Loaded sri.ini config file...")
        xvi_sri_major_version = config.get('Version','Major')
        logging.info(f"get_xvi_software_build_version_from_config(): XVI major softare version is: {xvi_sri_major_version}")
        xvi_sri_minor_version = config.get('Version','Minor')
        logging.info(f"get_xvi_software_build_version_from_config(): XVI minor software build version is: {xvi_sri_minor_version}")
        return [xvi_sri_major_version, xvi_sri_minor_version]
    except Exception as e:
        logging.exception(f"get_xvi_software_build_version_from_config(): Error obtaining XVI software build version: {e}")
        return ""

def get_xvi_major_software_version_from_remote_system(sri_config_path: str) -> Union[List[str], str]:
    '''
    Gets the major and minor software build version of the XVI app by reading the
    sri.ini config file on a remote XVI system using Squish's RemoteSystem library.

    Args:
        sri_config_path (str): Path to the XVI sri.ini config file.

    Returns:
        (List[str] or str): List of strings, the first string is the major version and the second
                            string is the minor version. If the config file cannot be read an
                            empty string or string error message is returned.
    '''
    result = remote_py_functions.execute_remote_py_function(get_xvi_software_build_version_from_config, [sri_config_path])

    if result is not None:
        return result
    return "Software build version not found"

def create_path_if_does_not_exist(dirPath: str) -> None:
    '''
    Create the given directory path if it does not exist.

    :param: dirPath (str), the directory path.
    '''
    rs = RemoteSystem()
    if rs.exists(dirPath) is False:
        rs.createPath(dirPath)

